	/**
	 * Default Constructor
	 */
    public DataSourceService(CurrentIdentity identity,
				ApplicationContext applicationContext)  {

		this.identity		= identity;
		this.projector 		= new DataSourceEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(DataSourceRepository.class) );
		this.validator		= applicationContext.getBean(DataSourceValidator.class) ;
	}


	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		DataSource
	 */
		public DataSource createDataSource( CreateDataSourceCommand command ) {

		DataSource entity = new DataSource();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setDataSourceId( command.getDataSourceId() );
            entity.setName( command.getName() );
            entity.setConnection( command.getConnection() );
            entity.setStreaming( command.getStreaming() );
            entity.setSourceType( command.getSourceType() );
            entity.setFormat( command.getFormat() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of DataSource {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdateDataSourceCommand
	 * @return		DataSource
	 */
	public DataSource updateDataSource( UpdateDataSourceCommand command ) {

		DataSource entity = new DataSource();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setDataSourceId( command.getDataSourceId() );
            entity.setName( command.getName() );
            entity.setConnection( command.getConnection() );
            entity.setStreaming( command.getStreaming() );
            entity.setWorkspace( command.getWorkspace() );
            entity.setProducedDatasets( command.getProducedDatasets() );
            entity.setPipelines( command.getPipelines() );
            entity.setSourceType( command.getSourceType() );
            entity.setFormat( command.getFormat() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of DataSource {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Deletes the associatied value object
	 * @param		command DeleteDataSourceCommand
	 */
	public void delete( DeleteDataSourceCommand command ) {
		UUID id = null;

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		id = command.getDataSourceId();

		// ------------------------------------------
		// delete the entity
		// ------------------------------------------
		projector.delete(id);

		LOGGER.info( "done deleting of DataSource {0} ", id );

	}

	/**
	 * Method to retrieve the DataSource via DataSourceFetchOneSummary
	 * @param 	summary DataSourceFetchOneSummary
	 * @return 	DataSourceFetchOneResponse
	 */
	public DataSource getDataSource( DataSourceFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "DataSourceFetchOneSummary arg cannot be null" );

		DataSource entity = null;
		UUID id = summary.getDataSourceId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a DataSource using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all DataSources
	 *
	 * @return 	List<DataSource>
	 */
    public List<DataSource> getAllDataSource() {
		List<DataSource> list = projector.findAll( new FindAllDataSourceQuery() );
		return list;
	}

	/**
	 * assign Workspace on DataSource
	 * @param		command AssignWorkspaceToDataSourceCommand
	 */
	public void assignWorkspace( AssignWorkspaceToDataSourceCommand command ) {
		// --------------------------------------
		// best to validate the command now
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.assignWorkspace(command.getDataSourceId(), command.getAssignment());

	}

	/**
	 * unAssign Workspace on DataSource
	 * @param		command UnAssignWorkspaceFromDataSourceCommand
	 */
	public void unAssignWorkspace( UnAssignWorkspaceFromDataSourceCommand command ) {

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.unAssignWorkspace(command.getDataSourceId());
	}
	

